use maho_rpc::session_worker_protocol::*;
#[test]fn worker_signal_survives_thread_envelope_transfer(){let signal=maho_rpc::session_worker_signals::WorkerSignal::default();let observed=signal.clone();let(send,receive)=std::sync::mpsc::channel();let thread=std::thread::spawn(move||{send.send(SessionWorkerToHost::Reserve{path:"/session".into(),signal}).unwrap();observed.wait(std::time::Duration::from_secs(2))});let message=receive.recv_timeout(std::time::Duration::from_secs(2)).unwrap();match message{SessionWorkerToHost::Reserve{path,signal}=>{assert_eq!(path,"/session");signal.acknowledge_grant(SessionWriteGrant::Limit);},_=>panic!("wrong worker envelope")};assert_eq!(thread.join().unwrap(),worker_credit_code(SessionWriteGrant::Limit));assert_eq!(serde_json::to_value(WorkerActivity{busy:true,handoff_busy:None,streaming:true}).unwrap(),serde_json::json!({"busy":true,"streaming":true}));}
#[test]fn host_envelopes_preserve_tags_and_optional_connection(){for value in [serde_json::json!({"type":"prepare","request":1,"configuration":{},"profile":{}}),serde_json::json!({"type":"commit","request":2}),serde_json::json!({"type":"bind","request":3,"sessionId":"lease","display":{"revision":1.0,"width":80.0,"rendered":false,"capabilities":[]}}),serde_json::json!({"type":"command","request":4,"command":{"type":"abort"},"connection":"peer","display":{"revision":1.0,"width":80.0,"rendered":false,"capabilities":[]}}),serde_json::json!({"type":"display","display":{"revision":1.0,"width":80.0,"rendered":false,"capabilities":[]}}),serde_json::json!({"type":"cancel_ui"}),serde_json::json!({"type":"close"})]{let parsed:HostToSessionWorker=serde_json::from_value(value.clone()).unwrap();assert_eq!(serde_json::to_value(parsed).unwrap(),value);}}
